<?php $edit=isset($_GET['edit'])?one("SELECT * FROM users WHERE id=? AND role='faculty'",[(int)$_GET['edit']]):false;?>
<div class="heading"><h1>Teaching Staff</h1></div>
<section class="card"><h2><?=$edit?'Edit teaching staff':'Add teaching staff'?></h2><p>Teaching staff use the public forms without a password. DAA, HoD and PL can also teach. Assign official roles and attendance access through Users & Notifications → Account directory.</p>
<form method="post"><?php csrf();?><input type="hidden" name="action" value="teaching_save"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><div class="form-grid"><label>Full name<input name="name" required maxlength="160" value="<?=e($edit['name']??'')?>"></label><label>Official email<input name="email" type="email" required maxlength="190" value="<?=e($edit['email']??'')?>"></label><label>Department<select name="department" required><option value="">Select department…</option><?php foreach(departments()as $dept):?><option <?=($edit['department']??'')===$dept?'selected':''?>><?=e($dept)?></option><?php endforeach;?></select></label></div><?php if(staffMetadataReady()):$profile=staffProfile((int)($edit['id']??0));?><label>Staff type<select name="staff_type"><?php foreach(['Regular','Adjunct']as $type):?><option <?=$profile['staff_type']===$type?'selected':''?>><?=e($type)?></option><?php endforeach;?></select></label><?php endif;?><button><?=$edit?'Save changes':'Add teaching staff'?></button><?php if($edit):?> <a href="?page=teaching">Cancel</a><?php endif;?></form></section>
<section class="card"><h2>Complete teaching staff list</h2><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Department / role</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach(teachingDirectory()as $teacher):?><tr><td><?=e($teacher['name'])?><small><?=e(staffProfile((int)$teacher['id'])['staff_type'])?></small></td><td><?=e($teacher['email'])?></td><td><?=e($teacher['department'])?><small><?=e(strtoupper($teacher['role']))?></small></td><td><?=$teacher['active']?'Active':'Inactive (history retained)'?></td><td><a href="?page=edit_user&id=<?=$teacher['id']?>">Assign role / teaching access</a><?php if($teacher['role']==='faculty'):?> <a href="?page=teaching&edit=<?=$teacher['id']?>"><?='Edit details'?></a><?php if($teacher['active']):?><form method="post" data-confirm="Disable this staff member? Their historical records will remain available."><?php csrf();?><input type="hidden" name="action" value="teaching_delete"><input type="hidden" name="id" value="<?=$teacher['id']?>"><button class="secondary">Disable</button></form><?php endif;endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="card"><h2>Bulk upload teaching staff</h2><p>Upload CSV or XLSX with Name, Email and Department columns. You can also use your historical substitution file if it contains these columns and one row per staff member. Use the exact department names shown above.</p><p>No password or login account is required. Existing emails are skipped; use Edit to change existing details. No notification emails are sent.</p><a href="?page=staff_template">↓ Download teaching staff template</a><form method="post" enctype="multipart/form-data"><?php csrf();?><input type="hidden" name="action" value="teaching_import_preview"><?php field('sheet','Teaching staff CSV or XLSX','file');?><button>Validate and preview staff</button></form></section>
<?php if(isset($_SESSION['teaching_import'])):?><section class="card"><h2>Review staff upload</h2><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Department</th><th>Action</th></tr></thead><tbody><?php foreach($_SESSION['teaching_import']as $item):?><tr><td><?=e($item['name'])?></td><td><?=e($item['email'])?></td><td><?=e($item['department'])?></td><td><?=e($item['result'])?></td></tr><?php endforeach;?></tbody></table></div><form method="post"><?php csrf();?><input type="hidden" name="action" value="teaching_import_commit"><button>Import teaching staff</button></form></section><?php endif;?>
